insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:systems-design-plant-engineer:tech-fast', 'systems-design-plant-engineer', 'tech-fast', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. System health monitoring starts from new failure modes and new performance data.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-liquid-metal']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 28, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:systems-design-plant-engineer:tech-msr', 'systems-design-plant-engineer', 'tech-msr', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"Factory-built modules for salt systems. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"وحدات مصنّعة في المصنع لأنظمة الأملاح. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Salt-wetted components bring new handling and inspection tasks. System health monitoring starts from new failure modes and new performance data.","text_ar":"تجلب المكونات الملامسة للملح مهام مناولة وفحص جديدة. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 29, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-engineer-core-physicist:tech-fast', 'reactor-engineer-core-physicist', 'tech-fast', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. System health monitoring starts from new failure modes and new performance data.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 30, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-engineer-core-physicist:tech-htgr', 'reactor-engineer-core-physicist', 'tech-htgr', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. System health monitoring starts from new failure modes and new performance data.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation, passive safety, factory fabrication and plant systems, coolant and fuel; digital I&C and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":2},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 31, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-engineer-core-physicist:tech-msr', 'reactor-engineer-core-physicist', 'tech-msr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"Factory-built modules for salt systems. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"وحدات مصنّعة في المصنع لأنظمة الأملاح. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Salt-wetted components bring new handling and inspection tasks. System health monitoring starts from new failure modes and new performance data.","text_ar":"تجلب المكونات الملامسة للملح مهام مناولة وفحص جديدة. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 32, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-engineer-core-physicist:tech-bwr', 'reactor-engineer-core-physicist', 'tech-bwr', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. System health monitoring starts from new failure modes and new performance data.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 33, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-fuel-specialist:tech-htgr', 'nuclear-fuel-specialist', 'tech-htgr', 1, false, '[{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. Fuel may arrive in different packages from the factory, changing receipt inspection and records.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. قد يصل الوقود في عبوات مختلفة من المصنع، فيتغير فحص الاستلام والسجلات."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. Refuelling intervals and tooling follow the new design.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. تتبع فترات التزويد بالوقود وأدواته التصميمَ الجديد."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. A different fuel form and handling chain, from receipt and storage to loading.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. شكل وقود وسلسلة مناولة مختلفان، من الاستلام والتخزين حتى التحميل."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are factory fabrication and plant systems, coolant and fuel; the maintenance regime adapts. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من نظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Criticality safety awareness, careful handling and complete records stay at the centre of the role.', 'يبقى الوعي بسلامة الحرجية والمناولة الحذرة والسجلات الكاملة في صميم الدور.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":2},{"skill_id":"sk-pf-01-advfuel","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-hydrogen"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 34, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-fuel-specialist:tech-fast', 'nuclear-fuel-specialist', 'tech-fast', 2, false, '[{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. Fuel may arrive in different packages from the factory, changing receipt inspection and records.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. قد يصل الوقود في عبوات مختلفة من المصنع، فيتغير فحص الاستلام والسجلات."},{"dim":"maintenance","change":"adapts","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. Refuelling intervals and tooling follow the new design.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. تتبع فترات التزويد بالوقود وأدواته التصميمَ الجديد."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. A different fuel form and handling chain, from receipt and storage to loading.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. شكل وقود وسلسلة مناولة مختلفان، من الاستلام والتخزين حتى التحميل."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are plant systems, coolant and fuel; factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Criticality safety awareness, careful handling and complete records stay at the centre of the role.', 'يبقى الوعي بسلامة الحرجية والمناولة الحذرة والسجلات الكاملة في صميم الدور.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-01-advfuel","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 35, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-fuel-specialist:tech-msr', 'nuclear-fuel-specialist', 'tech-msr', 3, false, '[{"dim":"factory_fab","change":"adapts","text_en":"Factory-built modules for salt systems. Fuel may arrive in different packages from the factory, changing receipt inspection and records.","text_ar":"وحدات مصنّعة في المصنع لأنظمة الأملاح. قد يصل الوقود في عبوات مختلفة من المصنع، فيتغير فحص الاستلام والسجلات."},{"dim":"maintenance","change":"adapts","text_en":"Salt-wetted components bring new handling and inspection tasks. Refuelling intervals and tooling follow the new design.","text_ar":"تجلب المكونات الملامسة للملح مهام مناولة وفحص جديدة. تتبع فترات التزويد بالوقود وأدواته التصميمَ الجديد."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. A different fuel form and handling chain, from receipt and storage to loading.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. شكل وقود وسلسلة مناولة مختلفان، من الاستلام والتخزين حتى التحميل."}]'::jsonb, 'Molten salt: the biggest shifts for this role are plant systems, coolant and fuel; factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في أنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Criticality safety awareness, careful handling and complete records stay at the centre of the role.', 'يبقى الوعي بسلامة الحرجية والمناولة الحذرة والسجلات الكاملة في صميم الدور.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-01-advfuel","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-fuel']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 36, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:cyber-security-engineer:tech-micro', 'cyber-security-engineer', 'tech-micro', 1, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'Microreactors: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-remote-ops','fr-digital-twin']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 37, 'p-training-mgr', '2026-10-11T08:00:00Z'),
